window.__BUNDLE__={"generatedAt":"2026-10-27T15:36:50.408826+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-20","archiveCutoff":"2021-10-28","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":353,"arxiv":1530,"total":1883},"freshness":{"latestPaperDate":"2026-10-27","latestPublishedDate":"2026-10-27","latestBatchCount":604,"newInLast24h":662,"newInLast48h":952},"historyTotal":27971,"topicCounts":{"Multi-Agent":3026,"Evaluation":15317,"Planning":2039,"Memory":543,"Code Agent":1121,"Interpretability":940,"Agentic RAG":1518,"Agentic Search":2020,"RL for LLM":1502,"Reasoning":7548,"Hallucination":1250,"Post-Training":3140,"Alignment":3674,"World Model":550,"Tool Use":1433,"Agent Safety":2689,"Computer Use":376,"Reflection":1005,"VLM Training":2191,"LLM Training":3577,"Fine-tuning":4329,"Multimodal Agent":163,"Agent Framework":940,"Error Attribution":180,"Data Engine":558},"count":36,"recentTotal":2727,"archiveCount":0,"archiveTotal":25244,"sources":{"hf":80,"arxiv":2647,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"title":"Trajectory2Gym: Decision-Grounded Compositional Interaction Synthesis for Tool-Use Agents","authors":["Yihao Hu","Zhihao Wen","Yitong Lin","Siyuan Lu","Pan Wang","Wei Wu","Jiang-Ming Yang","Tao Lin"],"submittedDate":"2026-10-24","tags":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"id":"arxiv:2610.33568","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33568","topics":["LLM Training","Tool Use","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33568","upvotes":325,"pdf":"https://arxiv.org/pdf/2610.33568.pdf","url":"https://arxiv.org/abs/2610.33568","abstract":"Successful tool-use trajectories are not necessarily useful supervision. Even successful interactions may underrepresent multi-step dependencies or contain actions that are unjustified by the information visible to the agent at decision time. We identify two coupled requirements for effective trajectory supervision: compositional coverage, so that important observation-action dependencies are represented, and decision grounding, so that each supervised action is supported by the learner-visible interaction history. We introduce Trajectory2Gym, which constructs executable interactions around under-supported compositional structures and derives supervision only from grounded decisions in their realized executions. Structural-support selection allocates the resulting experience, while parent-normalized supervised fine-tuning preserves the semantic interaction as the unit of training weight."},{"title":"StreamVibe: Proactive Video Agents for Evolving User Intent","authors":["Chengzhi Liu","Yuxiang Lai","Yuzhe Yang","Yanqing Liu","Jiheng Hou","Yue Cao","Haonan Wang","Ruixi Fan","Lan Wang","Sheng Liu","Songyou Peng","Yale Song","Kevin Qinghong Lin","Xin Eric Wang","Jui-Hsin Lai","Youbao Tang"],"submittedDate":"2026-10-26","tags":["VLM Training","Evaluation","Multimodal Agent"],"id":"arxiv:2610.34662","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34662","topics":["VLM Training","Evaluation","Multimodal Agent"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34662","upvotes":231,"pdf":"https://arxiv.org/pdf/2610.34662.pdf","url":"https://arxiv.org/abs/2610.34662","abstract":"Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., \"where should I click next?\" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation samples and 85K training samples spanning explicit, implicit, and dynamic intents. Building on this benchmark, we develop StreamVibe-VL, a streaming proactive model that infers implicit user intents from continuous observations and dynamically tailors its interactions as these intents evolve. We furthe"},{"title":"DynaFlow: Learning Free-Form Multi-Agent Orchestration","authors":["Ruhao Liu","Qi Li","Shizun Wang","Xinchao Wang"],"tags":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2610.34467","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34467","topics":["LLM Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2610.34467","upvotes":177,"pdf":"https://arxiv.org/pdf/2610.34467.pdf","url":"https://arxiv.org/abs/2610.34467","abstract":"Multi-agent systems often rely on predefined collaboration structures, limiting their ability to adapt to diverse task requirements. We introduce DynaFlow, a framework that integrates free-form executable workflow synthesis into the action space of the main agent. The agent decides when collaboration is needed and generates task-specific programs that coordinate sub-agents through sequential or parallel execution, structured information exchange, and verification. Execution results and traces inform subsequent actions, enabling the agent to adapt collaboration as reasoning progresses. We train only the main agent through supervised fine-tuning on distilled trajectories, followed by refinement on examples filtered for unsupported premises, biased verification, and information-flow defects. All sub-agents remain fixed, separating orchestration learning from executor capability improvement."},{"title":"InteractiveWorld: A Verifiable Human-Centric Environment for Building Better Interactive MLLM Assistants","authors":["Qinsi Wang","Wei Wen","Chong Zhou","Saksham Suri","Zechun Liu","Lemeng Wu","Hai Helen Li","Yiran Chen","Raghuraman Krishnamoorthi","Qi Qian"],"submittedDate":"2026-10-25","tags":["Planning","Evaluation"],"id":"arxiv:2610.33966","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33966","topics":["Planning","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33966","upvotes":107,"pdf":"https://arxiv.org/pdf/2610.33966.pdf","url":"https://arxiv.org/abs/2610.33966","abstract":"People have long dreamed of an assistant that is always there to guide them and remind what they forget, from new dishes to lost keys. Powered by multimodal large language models (MLLMs), egocentric AI assistants on wearable devices are bringing this dream within reach: they see what the user sees and give instructions for user's physical work when necessary. However, testing such assistance is challenging and usually requires real people. The expensive and rare real interaction data leaves a key question unanswered: Can today's MLLMs truly help people in physical world? To answer this question, we propose InteractiveWorld, the first verifiable environment for closed-loop interaction between human and AI assistant. Unlike existing robot-centric simulators, InteractiveWorld lets the assistant guide a human agent who observes the scene, understands instructions, and acts independently. It "},{"title":"Work Agents: Systems, Capabilities, and Optimization","authors":["Zishan Xu","Enjun Du","Mingqi Gao","Cheng Yang","Junhao Shen","Zirong Chen","Zhiyuan Yao","Yifu Guo","Yuquan Lu","Jinyang Huang","Zhengxi Lu","Siyi Liu","Ziyu Zheng","Yongqi Zhang","Difan Zou","Weiwen Liu"],"submittedDate":"2026-10-26","tags":["Evaluation"],"id":"arxiv:2610.35845","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35845","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35845","upvotes":91,"pdf":"https://arxiv.org/pdf/2610.35845.pdf","url":"https://arxiv.org/abs/2610.35845","abstract":"As foundation models evolve from information generation to digital work execution, agents are increasingly capable of completing complex tasks across tools, applications, and workflows. However, existing research lacks a unified perspective on how agents reliably accomplish delegated work. To address this gap, we present a work-centric, system-level perspective that views work agents as systems combining foundation models and runtime harnesses to execute tasks in stateful workspaces and deliver verifiable outcomes. We introduce two complementary dimensions, work persistence and work openness, to characterize working conditions, and classify digital work into five forms according to task scope and organization. Building on this framework, we identify five core capability families required for reliable work execution and examine approaches to model optimization, harness optimization, and t"},{"title":"WorldCast: World-Consistent Character Video Generation with Large-Angle Camera Control","authors":["Lei Cao","Yu Liu","Wenhua Liao","Peng Zhang","Fei Wang","Hao Zhang","Jiajun Le","Daiguo Zhou","Jian Luan","Jiayi Ma"],"submittedDate":"2026-10-23","tags":["Evaluation","Alignment"],"id":"arxiv:2610.33135","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33135","topics":["Evaluation","Alignment"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33135","upvotes":41,"pdf":"https://arxiv.org/pdf/2610.33135.pdf","url":"https://arxiv.org/abs/2610.33135","abstract":"Precise camera control is essential for cinematic character video generation, yet existing methods struggle to follow large-angle trajectories with combined rotation, translation, and radius variation from arbitrary initial azimuths. Such viewpoint changes also reveal character regions unseen in the initial frame, causing geometric distortions, appearance degradation, and identity drift. To systematically study these coupled challenges, we introduce CLACT, a large-scale Character-centric dataset and benchmark covering diverse Large-Angle Camera Trajectories, with accurate camera geometry and multi-view character observations for training and evaluation. We further propose WorldCast, a framework for world-consistent character video generation under diverse large-angle camera motions. Specifically, we back-project the initial frame into a 3D point cloud using estimated depth, align the poi"},{"title":"Spatial Audio Generation and Editing with Executable Plans and Self-Distilling Transfusion","authors":["Kam Man Wu","Yu Zhang","Pengjun Fang","Mingfei Chen","Weijia Chen","Zeyue Tian","Qifeng Chen"],"submittedDate":"2026-10-25","tags":["Planning"],"id":"arxiv:2610.34415","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34415","topics":["Planning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34415","upvotes":36,"pdf":"https://arxiv.org/pdf/2610.34415.pdf","url":"https://arxiv.org/abs/2610.34415","abstract":"Spatial audio authoring coordinates source decisions with soundfield synthesis. For editing, plans specify what to change and retain, while reference audio supplies further acoustic detail. We present AMBIT, a unified framework for native First-Order Ambisonics (FOA) generation and editing with three connected contributions. First, a shared Transfusion backbone couples autoregressive planning with rectified-flow rendering through executable ScenePlans that specify source content, activity, and 3D trajectories. For editing, the plan describes the full target scene, including retained sources; contrastive features ground the requested change, while full reference latents supply residual acoustic detail for preservation. Second, an FOA-aware continuous VAE combines shared-decoder omnidirectional recovery, asymmetric grouped KL, and spatial covariance matching to preserve content and inter-c"},{"title":"Continual Learning Exam: Benchmarking Long-Horizon RSI and Experiential Learning in LLM Agents","authors":["Haoyu Zhao","Sitian Tu","Yuxuan Huang","Huichi Zhou","Zhangyue Yin","Jiahao Huang","Jingyuan Xu","Tianmiao Shi","Jin Shi","Nianxi Zhang","Yangmiao Zhang","Zhuolang Chan","Huiyan Hu","Chenchao Sheng","Yaqing Luo","Yue Chen","Huaxiu Yao","Meng Fang","Jun Wang"],"submittedDate":"2026-10-25","tags":["Evaluation"],"id":"arxiv:2610.33956","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33956","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33956","upvotes":36,"pdf":"https://arxiv.org/pdf/2610.33956.pdf","url":"https://arxiv.org/abs/2610.33956","abstract":"Continual learning is the ability of LLM agents to improve over time by acquiring, refining, and applying knowledge from experience while retaining useful prior knowledge. It is essential for agents learning over long time horizons, yet current evaluations largely assess individual task performance rather than improvement through accumulated experience. We introduce Continual Learning Exam (CLE), a large-scale benchmark developed by 50+ domain experts to measure experience-driven improvement in realistic professional workflows. CLE comprises 120 human-authored tasks, each organised as a five-level ladder, yielding 600 levels spanning 89 professional roles across 12 occupational domains. Agents must pass each level to unlock the next, with later levels building on experience accumulated during earlier assignments. An evaluation agent assesses each submission against human-authored rubrics"},{"title":"$Δτ$-Bench: Pushing Agents Toward a Moving Capability","authors":["Shuofei Qiao","Xuanguang Pan","Yijun Chen","Wendi Feng","Bin Wu","Runnan Fang","Yuqi Zhu","Shumin Deng","Emine Yilmaz"],"submittedDate":"2026-10-25","tags":["Tool Use","Evaluation"],"id":"arxiv:2610.34238","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34238","topics":["Tool Use","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34238","upvotes":19,"pdf":"https://arxiv.org/pdf/2610.34238.pdf","url":"https://arxiv.org/abs/2610.34238","abstract":"In this paper, we introduce $Δτ$-Bench, an executable agent benchmark that models the structural evolution of large tool ecosystems. In $Δτ$-Bench, independently evolving services continually reshape how tasks can be accomplished: familiar tools may disappear or be replaced, while more efficient alternatives emerge amid overlapping functionality and noisy documentation. Against this moving capability frontier, we evaluate whether agents can proactively discover efficient tool-use paths and promptly revise their accumulated procedural knowledge, bringing together demands that existing benchmarks fail to examine. $Δτ$-Bench comprises 1,588 validated multi-turn tasks across 42 domains and six successive ecosystem states generated through capability-preserving transformations. Our evaluation shows that even the strongest evaluated model or harness achieves only 42.3% task success, while init"},{"title":"Qwen-Image-PE: Learning Visual Design for Text-to-Image Prompt Enhancement","authors":["Zekai Zhang","Yanran Zhang","Shengming Yin","Yan Shu","Zhening Liu","Bingxuan Zhao","Chenyang Zhu","Donghao Zhou","Jiahao Li","Jiahao Wang","Jie Zhang","Kaiyuan Gao","Kun Yan","Lihan Jiang","Ningyuan Tang","Qihang Ai","Rui Song","Shuo Cao","Xiao Xu","Xiaoyue Chen","Yuxiang Chen","Zhendong Wang","Zhouyang Li","Zihao Liu","Zikai Zhou","Bo Zheng","Huishuai Zhang","Dongyan Zhao","Chenfei Wu"],"submittedDate":"2026-10-24","tags":["LLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2610.33472","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33472","topics":["LLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33472","upvotes":18,"pdf":"https://arxiv.org/pdf/2610.33472.pdf","url":"https://arxiv.org/abs/2610.33472","abstract":"Learning visual design is essential for prompt enhancement (PE) to turn underspecified user requests into coherent visual specifications for text-to-image (T2I) generation. Existing methods preserve user intent and improve overall visual appeal, with less explicit emphasis on fine-grained design dimensions. To address this gap, we introduce Qwen-Image-PE, which learns visual design through two-stage training. Supervised fine-tuning with Caption-Based Reverse Distillation (CRD) uses dense captions of well-designed images as design supervision. Reinforcement learning with Groupwise Design Reward (GDR) jointly compares all candidate images for the same request to refine lighting, composition, layout, and detail. On Qwen-Image-Bench with Qwen-Image-2.1, Qwen-Image-PE-397B improves over original requests by 7.81 points, while Qwen-Image-PE-9B outperforms all evaluated PE baselines. Further ev"},{"title":"Trustworthy Recursive Self-Improvement in the Era of Large Models: Foundation, Risks, Evaluation and Open Challenges","authors":["Jiayue Pu","Ang Gao","Jinyi Bai","Qipeng Wang","Tongyu Wen","Jiahao Zhao","Keyu Qu","Junhao Zhang","Chenglei Shen","Zhongxiang Sun","Jun Xu","Xiao Zhang"],"submittedDate":"2026-10-26","tags":["Evaluation","Alignment","Reflection"],"id":"arxiv:2610.35193","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35193","topics":["Evaluation","Alignment","Reflection"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35193","upvotes":16,"pdf":"https://arxiv.org/pdf/2610.35193.pdf","url":"https://arxiv.org/abs/2610.35193","abstract":"AI systems built around large models increasingly use experience and feedback to make persistent changes to models, prompts, memories, tools, and workflows. Recursive self-improvement (RSI) extends this process to inductive biases and to the mechanisms that govern future updates, which can themselves be revised and reused across improvement cycles. Yet self-modification alone does not guarantee trustworthy improvement. Reported gains may reflect flawed evaluations, previously acquired capabilities may deteriorate, and compliance with behavioral constraints may weaken. Compromised artifacts or sensitive information may also persist in successor systems. Changes to improvement mechanisms may invalidate earlier verification results and make human oversight less effective. This survey presents an operational definition and process framework for RSI and organizes the requirements for trustwor"},{"title":"S3AC: Stabilized, Selective, and Scalable Actor-Critic for LLM Reasoning","authors":["Shuo Shen","Guangran Cheng","Chengqi Lyu","Xiangsen Wang","Yanan Sun","Wenwei Zhang"],"submittedDate":"2026-10-26","tags":["Post-Training","Reasoning","RL for LLM"],"id":"arxiv:2610.35518","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35518","topics":["Post-Training","Reasoning","RL for LLM"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35518","upvotes":11,"pdf":"https://arxiv.org/pdf/2610.35518.pdf","url":"https://arxiv.org/abs/2610.35518","abstract":"Critic-free methods are widely used in reinforcement learning with verifiable rewards (RLVR) for long chain-of-thought (CoT) reasoning, avoiding difficult and costly critic training. Common alternatives lack token-level credit assignment and typically rely on grouped rollouts to estimate prompt-specific baselines. A critic can address both limitations, but long-CoT critic training is hindered by insufficient coverage of trajectories with diverse lengths and early gradients dominated by the newly initialized value head. We introduce S3AC (Stabilized, Selective, and Scalable Actor-Critic) for LLM reasoning, built around a practical critic-training recipe. The trained critic provides token-specific advantages and prompt-specific baselines. Using the prompt-level baseline to estimate difficulty, we propose Difficulty-Aware Prompt Sampling (DAPS). DAPS combines this estimate with outcome hist"},{"title":"EmbodiedLab: Benchmarking Embodied Agents That Act to Know","authors":["Hongcheng Gao","Zelin Zheng","Alex Zhou","Jay Zhu","Shijia Ge","Yazhe Wang","Xiping Li","Jianshu Zeng","Di Wu","Xuan Shangguan","Yexing Wan","Lingyu He","Yongli Wang","Xiaohan Yu","Zhiqi Jia","Yue Liu","Bryan Hooi","Yinpeng Dong","Wentao Zhang","Sihang Wu","Xiao He"],"tags":["Planning","Code Agent","Evaluation"],"id":"arxiv:2610.35385","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35385","topics":["Planning","Code Agent","Evaluation"],"arxiv":"https://arxiv.org/abs/2610.35385","upvotes":9,"pdf":"https://arxiv.org/pdf/2610.35385.pdf","url":"https://arxiv.org/abs/2610.35385","abstract":"Embodied agents are expected to accomplish real-world goals by deciding for themselves how and when to interact with their surroundings. For many such goals, changing the physical state of the world is the means rather than the end: the agent changes the state of a system through interaction, observes the feedback, and explores until it either achieves the goal itself (e.g., discovering physical laws) or learns what the goal requires; it acts to know. Manipulation benchmarks stop at acting to change, with the target state given; scientific discovery benchmarks evaluate knowing but replace physical experimentation with symbolic actions or numerical queries. We introduce EmbodiedLab, a benchmark in which a robot must act to know. Quantitative science experiments make this setting controllable: the parameters of the system are resampled for every instance, so the result cannot be known in a"},{"title":"RynnVLA-Latent: Scaling Robotic Manipulation Foundation Models with 3D-Grounded Latent Actions","authors":["Haoyu Zhao","Xingyue Zhao","Zhian Su","Bohan Hou","Yinzhou Tang","Fengyi Wang","Kehan Li","Yuming Jiang","Siteng Huang","Xin Li","Zhenyu Zeng","Mingxiu Chen","Deli Zhao","Zhongyu Li"],"tags":["LLM Training","VLM Training","Evaluation"],"id":"arxiv:2610.34356","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34356","topics":["LLM Training","VLM Training","Evaluation"],"arxiv":"https://arxiv.org/abs/2610.34356","upvotes":9,"pdf":"https://arxiv.org/pdf/2610.34356.pdf","url":"https://arxiv.org/abs/2610.34356","abstract":"Scaling vision-language-action (VLA) models is constrained by scarce action-labeled demonstrations and incompatible control spaces across robot embodiments. We present RynnVLA-Latent, a framework that turns heterogeneous interaction videos into scalable supervision for robot policy pretraining. At its core, RynnLAM learns continuous, 3D-grounded latent actions from visual transitions without requiring native robot controls. By combining residual future-feature prediction, camera-compensated 3D-flow supervision, and camera-motion decoupling, RynnLAM encourages representations that capture control-relevant motion rather than appearance changes alone. We apply RynnLAM to 30.1K hours of human, robot, and simulation videos, producing 745.52M latent-action descriptors. RynnVLA-Latent then learns to predict latent-action chunks from visual observations and language through flow matching, before"},{"title":"Build, Don't Play: Self-Improving LLM Research Agents Develop a Hearthstone Battlegrounds AI That Rivals Top Players","authors":["Changlian Ma","Limin Wang"],"submittedDate":"2026-10-24","tags":["Agentic Search","Evaluation"],"id":"arxiv:2610.33845","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33845","topics":["Agentic Search","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33845","upvotes":8,"pdf":"https://arxiv.org/pdf/2610.33845.pdf","url":"https://arxiv.org/abs/2610.33845","abstract":"Can LLM agents carry a hard real-world problem from raw data to a system that holds its own against people? We study this in Hearthstone Battlegrounds, an eight-player auto-battler with stochastic shops and battles, hidden information and nearly a thousand interacting cards. We present AutoTavern, a self-improving research system: specialised LLM research agents share a typed research memory, every claim passes verification gates, and live games close the loop, so the agents improve the simulator, opponents and policy and, from the same feedback, their own research process; a human sets goals and rules on ambiguous mechanics. In 20 days AutoTavern built TavernGym, the first faithful, full-content reproduction of the live game, and delivered 23 versions of TavernAgent, trained with PPO against opponents calibrated to real games. TavernAgent plays complete games on the live ladder by itsel"},{"title":"Novel or Not? PatEx-Gym: Agentic Prior-Art Search for Novelty Assessment in Patent Examination","authors":["Qiyao Wang","Xinyi Chen","Hongbo Wang","Jiayuan Lu","Jianhang Li","Minghuan Tan","Yuan Lin","Min Yang"],"submittedDate":"2026-10-24","tags":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2610.33503","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33503","topics":["Agentic Search","LLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33503","upvotes":6,"pdf":"https://arxiv.org/pdf/2610.33503.pdf","url":"https://arxiv.org/abs/2610.33503","abstract":"Patent examination is a challenging real-world task that requires agents to discover sparse prior art, iteratively refine queries, inspect technical evidence, and produce novelty assessments documented in Office Actions (OAs) across heterogeneous scientific and technical domains. However, existing benchmarks largely focus on static and limited candidate sets, leaving the full search--reasoning--assessment process underexplored. We present PatEx-Gym, the first framework for developing and evaluating agents for patent examination, which integrates three components. First, PatEx-Bench provides 1K realistic examination tasks, two large-scale retrieval corpora containing over 1M patents and 52K scientific papers, and a harness runtime supporting iterative search, document visits, reasoning, and OA generation. Second, we introduce PASS, an annotation-free Prior-Art Agentic Search Trajectory Sy"},{"title":"AgentProofBench: Benchmarking Reusable Verifiers for Web Agents","authors":["Jingjie Ning","Xueqi Li","Yi Lu","Yibo Kong"],"submittedDate":"2026-10-25","tags":["Computer Use","Evaluation"],"id":"arxiv:2610.34634","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34634","topics":["Computer Use","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34634","upvotes":5,"pdf":"https://arxiv.org/pdf/2610.34634.pdf","url":"https://arxiv.org/abs/2610.34634","abstract":"Reusable Web-agent verification requires a rule to follow changing requirements and support subsequent execution. We introduce AgentProofBench, which connects paired tests of a frozen acceptance rule to execution from identical saved openings. The resource spans 97 tasks, 79 families, and four Web services. Experiments with DeepSeek Flash/Pro establish two linked measurements. Across 48 families, complete-panel and decision-replay tests retain 82/96 Flash and 79/96 Pro source programs; paired reuse-rebuild BA intervals are [-5.47, 1.57] and [-10.16, 0.00] percentage points. Across 22 execution families, deployment-state panel correctness separates program assignments whose two saved openings are both delivered correctly: 32/33 assignments with error-free panels, versus 1/11 with panel errors. All reference-defined program-gate regressions and withheld deliveries occur in the latter group"},{"title":"Skill$^{\\infty}$: Recursive Self-Improvement for Agent Skill Optimization","authors":["Wangcheng Tao","Zhanglu Yan","Han Wu","Weng-Fai Wong"],"submittedDate":"2026-10-26","tags":["Reflection"],"id":"arxiv:2610.35434","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35434","topics":["Reflection"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35434","upvotes":3,"pdf":"https://arxiv.org/pdf/2610.35434.pdf","url":"https://arxiv.org/abs/2610.35434","abstract":"Recursive self-improvement (RSI), in which a system also improves the way it improves, is a long-standing aspiration on the path to AGI. Language agents increasingly store procedural knowledge in reusable skills. Optimizing skills offers a direct way to achieve RSI, because the optimization procedure itself can be encoded as a skill. Existing skill optimizers, however, follow a hand-designed procedure. Even methods that evolve a meta-skill confine it to a fixed pipeline and relearn it for each task. We present Skill$^{\\infty}$, which makes skill optimization recursively self-improving: a meta agent follows a meta-skill to optimize task skills and optimizes the meta-skill itself using the same procedure. The optimization is agent-led. The meta agent diagnoses execution traces, proposes candidates, requests independent reviews, and allocates the search budget. The meta-skill defines these "},{"title":"Thinking-in-Bets at Test Time Reduces Sycophantic Revisions in LLM Agents","authors":["Nghi D. Q. Bui"],"submittedDate":"2026-10-26","tags":["Reasoning","Evaluation"],"id":"arxiv:2610.34654","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34654","topics":["Reasoning","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34654","upvotes":2,"pdf":"https://arxiv.org/pdf/2610.34654.pdf","url":"https://arxiv.org/abs/2610.34654","abstract":"Language model agents often abandon correct work when a user challenges it, yet simply telling them to stand firm makes them ignore real mistakes. Once an agent reads a complaint, it tends to discount its own earlier checks in order to agree with the user. We introduce Thinking-in-Bets, a training-free method in which an agent writes a short private record of its main claims, the checks supporting them, and its confidence before reading user feedback. When challenged, the agent consults this Claim Checklist to keep verified work intact while investigating uncertain or newly challenged parts. We evaluate five Gemini models (3.5 Flash-Lite, 3.5 Flash, 3.6 Flash, 3.8 Flash, and 4.0 Argon) across eight benchmarks: SWE-Together, SWE-Interact, and DeepSWE for software engineering, Agents' Last Exam for professional reports, Humanity's Last Exam and SycEval for academic reasoning, Vals Finance "},{"title":"Mycelium: A Meta-Study of Hallucination Detection Across Provenance, Typology, and Granularities","authors":["Julia Belikova","Elisei Rykov"],"submittedDate":"2026-10-24","tags":["Hallucination","Evaluation"],"id":"arxiv:2610.33608","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33608","topics":["Hallucination","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33608","upvotes":2,"pdf":"https://arxiv.org/pdf/2610.33608.pdf","url":"https://arxiv.org/abs/2610.33608","abstract":"Hallucination detection is increasingly important for evaluating and deploying large language models. However, existing methods are often compared across benchmarks that define and measure hallucination in substantially different ways, making reported scores difficult to interpret across settings. We study hallucination detection as a benchmark-conditioned measurement problem and organize existing benchmarks along three axes: provenance, which describes how model outputs and evidence conditions are obtained; typology, which captures the factuality and faithfulness failures represented by benchmark labels; and granularity, which specifies the unit at which hallucinations are annotated, predicted, and evaluated. Using this framework, we analyze how benchmark construction, annotation, and evaluation choices shape the underlying prediction task, and relate detector mechanisms and assumptions"},{"title":"Humans in Space: Can MLLMs Construct Human-Centric Spatial Understanding via Active Exocentric Exploration?","authors":["Tianchen Guo","Tengyue Zhang","Chen Liu","Ling Chen","Xin Yu"],"submittedDate":"2026-10-25","tags":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2610.34149","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34149","topics":["Post-Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34149","upvotes":1,"pdf":"https://arxiv.org/pdf/2610.34149.pdf","url":"https://arxiv.org/abs/2610.34149","abstract":"While Multimodal Large Language Models (MLLMs) excel at zero-shot reasoning, their spatial capabilities are primarily evaluated through static, passive observation. In complex, human-centric scenes, occlusion often hides crucial geometric evidence, and passive benchmarks force models to guess rather than recognize their own visual uncertainty. To bridge this gap, we introduce SATE-Bench, a novel interactive benchmark comprising 316 real-world scenes and 2,525 multi-turn QA pairs to evaluate visual self-awareness and active exocentric view-exploration. It combines a Passive multi-view control with an Active exploration setting, where models start from a severely occluded view and must iteratively query adjacent viewpoints until they gather enough evidence to fully ``sate'' the question, scored by a step-penalized efficiency reward. Evaluating state-of-the-art MLLMs reveals that they termi"},{"title":"Beyond Benchmarks: Can Small Open-Weight Models Get Real Coding Work Done?","authors":["Vaibhav Jain"],"submittedDate":"2026-10-25","tags":["Evaluation"],"id":"arxiv:2610.34241","source":"hf","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.34241","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34241","upvotes":1,"pdf":"https://arxiv.org/pdf/2610.34241.pdf","url":"https://arxiv.org/abs/2610.34241","abstract":"Making an open-weight language model generate text is not the same as making it finish coding work. This retrospective empirical systems experience report follows my engineering work from July to October 2026 across coding clients, model-specific serving recipes, vLLM, SGLang, llama.cpp, and MLX. Models behind a nominally compatible endpoint still differed in tool-call formatting, turn control, context behavior, cache reuse, and reliability. A served model, coherent text, executed tool calls, and code that passes independent behavioral checks proved to be distinct levels of progress. The evidence includes 4,165 coding-agent gateway turns from my own sessions, 623 debug jobs, and three separate delegation studies with hidden behavioral checks and a fixed Claude Opus 5.5 parent. Saved cold-prefix requests had a median time to first token of about 69.4 s, versus 2.8 s for high-reuse request"},{"title":"AV-FABLE: Audio-Visual Manipulation Forensics in Long-Form Videos","authors":["Yuesheng Huang","Hoi Fan Au","Jiaqi Hou","Ruicheng Zhang","Jiarui He","Haocheng Yang","Bin Hu","Kewei Zhang","Weijian Deng","Jun Zhou","Xiu Li"],"submittedDate":"2026-10-24","tags":["Evaluation"],"id":"arxiv:2610.33413","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33413","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33413","upvotes":26,"pdf":"https://arxiv.org/pdf/2610.33413.pdf","url":"https://arxiv.org/abs/2610.33413","abstract":"Localized AI manipulations in long-form videos often affect brief events within otherwise authentic content, making video-level classification insufficient for forensic analysis. Existing audio-visual deepfake benchmarks largely focus on short talking-head clips, while long-form temporal forensics remains predominantly visual. We introduce AV-FABLE, a dual-timeline benchmark for sparse manipulations in open-scene long-form audio-visual videos. AV-FABLE contains 16,650 pristine--manipulated twin pairs (998 hours) created with 27 editing configurations, with separate audio and visual timelines that enable modality-specific temporal localization and expose errors hidden by joint-timeline evaluation. On AV-FABLE, zero-shot prompting of audio-visual large language models (AV-LLMs) yields near-chance detection and poor temporal localization. In contrast, supervised readouts of their frozen per"},{"title":"Evolving to Match Capabilities: Improving Harness Self-Evolution via Skill Adaptation","authors":["Zhihao Yang","Haojin Wang","Juncheng Wu","Kuan Zhang","Yukun Chen","Run Luo","Yaojie Lu","Yuyin Zhou","Lu Wang","Xianpei Han"],"submittedDate":"2026-10-10","tags":["Evaluation"],"id":"arxiv:2610.33024","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33024","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33024","upvotes":10,"pdf":"https://arxiv.org/pdf/2610.33024.pdf","url":"https://arxiv.org/abs/2610.33024","abstract":"Harness self-evolution offers a practical route for LLM agents to improve from execution experience without updating model parameters. Its effectiveness depends on whether models can successfully act on the guidance provided by their harnesses. However, we find that harness benefits are not uniform across model capabilities: skills that improve stronger models can provide little benefit or even degrade performance for weaker ones. Across seven models and three benchmarks, we identify 103 task-skill pairs where skills improve GPT-5.6-luna by 31.1 points but degrade Gemma-4-E4B by 8.8 points. In 86% of failed weak-model runs, the violated requirement is already stated in the skill. This motivates skill adaptation: reformulating existing skills to match the executor's capabilities and make their guidance easier to execute. To achieve this, we diagnose failures in tool execution, context man"},{"title":"Skip the Compressor: Coding Agents Fix More Issues When They Pick Whole Files","authors":["Xiaocong Yang","Rishit Chatterjee","Himanshu Udupi","Vikram Ramavarapu","ChengXiang Zhai"],"submittedDate":"2026-10-15","tags":["Code Agent","Evaluation"],"id":"arxiv:2610.21073","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.21073","topics":["Code Agent","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.21073","upvotes":3,"pdf":"https://arxiv.org/pdf/2610.21073.pdf","url":"https://arxiv.org/abs/2610.21073","abstract":"A coding agent works on repositories that can be far larger than its context window can hold. Prompt compressors and retrievers offer solutions to this problem, but patching an issue needs two things at once: the files that must change, and their code exactly as written, since the model must reproduce the lines it edits. Retrievers rank code by its similarity to the issue rather than by whether it must change, and compressors delete text to fit the budget. We show that at an equal token budget, an agent resolves more issues when the budget goes to choosing which files to show verbatim, as our simple selector CQ2-CARE does, than when it goes to pruning tokens or retrieving chunks. We fit every context to the same per-issue budget on 300 recent SWE-rebench issues and grade each patch with the benchmark's tests. With GPT-5.6 and Claude Opus 5, CQ2-CARE resolves 43.7% and 46.7% of the issues"},{"title":"OBB-PBD: Extending Parallel Box Decoding to Oriented Bounding Boxes for Referring Expression Grounding in Aerial Imagery","authors":["Chang Woo Song","Yeong Jun Koh"],"submittedDate":"2026-10-26","tags":["Evaluation"],"id":"arxiv:2610.35450","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35450","topics":["Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35450","upvotes":2,"pdf":"https://arxiv.org/pdf/2610.35450.pdf","url":"https://arxiv.org/abs/2610.35450","abstract":"Referring expression grounding in overhead imagery requires oriented bounding boxes rather than horizontal ones, since aerial objects appear at arbitrary orientations. Most grounding models emit box coordinates sequentially; Parallel Box Decoding (PBD) instead predicts all geometry slots in one forward pass, but only for four-coordinate horizontal boxes. We extend this block-aligned interface to a six-slot oriented representation using a double-angle parameterization. Rather than assuming correctness from a decreasing loss curve, we verify the extension with image/prompt-shuffle controls and visibility/leakage probes, which show that the corrected model depends on both the image and the prompt rather than on prompt statistics alone. On the aerial vehicle visual grounding (AVVG) benchmark, whose targets are genuinely oriented, the extended model improves rotated intersection over union (r"},{"title":"RoboJev: An Open Vision-Language Judge for Robot Success Detection","authors":["Josef Liyanjun Chen"],"submittedDate":"2026-10-24","tags":["VLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2610.33718","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.33718","topics":["VLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33718","upvotes":1,"pdf":"https://arxiv.org/pdf/2610.33718.pdf","url":"https://arxiv.org/abs/2610.33718","abstract":"Many robot manipulation videos do not indicate whether the task was successfully completed. RoboJev-27B is an open-weight vision-language model that takes a task instruction, 10 frames of a manipulation attempt, and (if available) final frames from auxiliary cameras and predicts whether the robot accomplished the task. RoboJev-27B is a variant of JEV-27B-VL, trained with a rank-32 LoRA adapter on the language model only (keeping the vision encoder frozen) using 52,598 episode records. It also uses a source-specific KL penalty that applies only to research data, anchoring predictions closer to the original model on those sources. It uses a calibrated two-token readout that outputs success/failure probabilities in a single forward pass. On 268 held-out episodes of the same robot model (SO-101), RoboJev-27B attains 95.2% balanced accuracy and 0.993 AUROC. It also generalises to episodes col"},{"title":"Constrained Decoding: Harmful or Beneficial? Revisiting Its Impact on LLM Performance","authors":["Ngoc Trinh Hung Nguyen","Alonso Silva","Armen Aghasaryan","Mehwish Alam"],"submittedDate":"2026-10-26","tags":["Reasoning","Evaluation"],"id":"arxiv:2610.35328","source":"arxiv","date":"2026-10-27","hfUrl":"https://huggingface.co/papers/2610.35328","topics":["Reasoning","Evaluation"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35328","upvotes":1,"pdf":"https://arxiv.org/pdf/2610.35328.pdf","url":"https://arxiv.org/abs/2610.35328","abstract":"Constrained decoding guarantees that Large Language Models (LLMs) produce outputs conforming to predefined formats, but is often assumed to inherently degrade reasoning. We examine this assumption through a taxonomy of three constraint types: \\emph{format constraints}, which enforce output structure; \\emph{validity constraints}, which mask invalid answer; and \\emph{reasoning constraints}, which restrict reasoning trajectories. We theoretically show that appropriate constraints can preserve or improve performance by eliminating invalid paths. Across four model families and eleven open-source models, causal ablations on diverse benchmarks using state-of-the-art constrained decoding strategies reveal that apparent performance degradation largely stems from non-equivalent prompting and output formats rather than from decoder-level masking. Meanwhile, validity constraints improve reliability "},{"title":"Large Language Models: A Plain-Language Overview for Engineers","authors":["Bahaeddin Türkoğlu"],"submittedDate":"2026-10-25","tags":["Agentic RAG","Agentic Search","Post-Training","LLM Training","Reasoning"],"id":"arxiv:2610.34585","source":"arxiv","date":"2026-10-27","topics":["Agentic RAG","Agentic Search","Post-Training","LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34585","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.34585.pdf","url":"https://arxiv.org/abs/2610.34585","abstract":"Large language models (LLMs) are neural networks trained on huge text collections to generate text by predicting what comes next. Engineers using ChatGPT and other generative artificial intelligence (AI) tools need a clear picture of what training changes and prompts add. The article starts with the Transformer, which connects words in context, and pre-training, where models learn to predict text. It then explains how fine-tuning adapts models to requests, with reinforcement learning from human feedback using human answer rankings. Next, retrieval-augmented generation (RAG) supplies documents, while chain-of-thought prompting encourages intermediate steps and agents use tools. FlashAttention lowers training and running costs by reducing data movement during attention; quantized low-rank adaptation (QLoRA) saves fine-tuning memory. Readers get a life cycle figure and tables comparing meth"},{"title":"A Comprehensive Framework for All Stages of Large-Model Training: From Data and Tokenization, through Pretraining, to Post-Training Alignment","authors":["Xiangjing An","Zhibin Jiao","Aiting Chen"],"submittedDate":"2026-10-24","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Alignment"],"id":"arxiv:2610.33451","source":"arxiv","date":"2026-10-27","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Alignment","Fine-tuning","RL for LLM"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33451","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.33451.pdf","url":"https://arxiv.org/abs/2610.33451","abstract":"The capabilities of large language models (LLMs) and multimodal LLMs (MLLMs) arise from the synergy of the full training pipeline, including data and tokenization, pretraining, and post-training (supervised fine-tuning, preference alignment, reinforcement learning, and continual optimization), rather than any individual stage. Existing surveys mostly adopt a single-stage or single-technique perspective, treating related research as isolated systems without unified stage division or a horizontally comparable basis. This paper proposes a unified stage division and a six-dimensional analytical framework covering data, objective function, optimization strategy, system constraints, evaluation, and risk and governance. We systematically review 395 core references from 2017 to 2026, and present a conceptual map of cross-stage effects: forward constraints of pretraining on post-training, and rev"},{"title":"Audio-R1: Audio Reasoning through Reinforcement Learning on Self-Supervised Tasks","authors":["Jihoon Jeong","Mirco Ravanelli","Zhepei Wang","Cem Subakan"],"submittedDate":"2026-10-25","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"id":"arxiv:2610.34609","source":"arxiv","date":"2026-10-27","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34609","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.34609.pdf","url":"https://arxiv.org/abs/2610.34609","abstract":"Reasoning is increasingly important for large audio-language models (LALMs), yet remains relatively underexplored compared with text-only and vision-language models. We introduce Audio-R1, a reinforcement learning (RL) post-training framework that revisits audio self-supervised learning as a source of verifiable rewards for improving audio understanding and reasoning task performance. Audio-R1 uses answers automatically determined during the construction of self-supervised tasks to verify model responses and compute rewards. Experiments across multiple LALMs and diverse audio benchmarks show consistent performance gains, while ablations demonstrate the benefits of each self-supervised task and additional gains from joint training. While both supervised fine-tuning and Audio-R1 improve self-supervised task accuracy, Audio-R1 further improves performance on downstream tasks distinct from t"},{"title":"GRASP: Group-Adaptive Hybrid RL-SFT Post-Training for Medical VQA without Reasoning Annotations","authors":["Wanqi Dong","Wanyue Dong","Jingze Ge","Mehul Motani"],"submittedDate":"2026-10-25","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"id":"arxiv:2610.34561","source":"arxiv","date":"2026-10-27","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34561","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.34561.pdf","url":"https://arxiv.org/abs/2610.34561","abstract":"Adapting general-purpose vision-language models (VLMs) to medical visual question answering (VQA) is valuable for helping clinicians read images and make diagnoses, but annotated data are scarce and provide only short answers, without reasoning annotations. Supervised fine-tuning (SFT) fits these labels but overfits to them and amplifies their biases, eroding out-of-domain (OOD) generalization. Reinforcement learning (RL) better preserves generalization but never uses the gold answer as a training target: GRPO-style algorithms learn from the contrast between correct and incorrect answers within a group of sampled responses, so all-correct or all-wrong groups give no correctness signal. Existing SFT-RL hybrids either apply SFT and RL in separate stages or switch between them per question, or need reasoning traces from experts or stronger models, which medical VQA data lack. We propose GRA"},{"title":"RobotAgentBench: Towards Open-world Robot Autonomy","authors":["Lingjun Mao","Jinglin Cao","Lukun He","Wenpeng Xu","Yuchen Yan","Hengyu Jin","Zijun Zhang","Jinzhou Tang","Songyao Jin","Ziche Liu","Yifei Shao","Junbo Huang","Fang Nan","Ruobing Han","Ziqiao Xi","Ziming Xu","Shuang Liang","Sibo Zhu","Wenyi Wu","Xinyue Wang","Yiming Huang","Xinkai Zou","Gao Zhu","Kun Zhou","Biwei Huang"],"submittedDate":"2026-10-26","tags":["Agent Safety","Reasoning","Planning","Evaluation","Reflection"],"id":"arxiv:2610.34649","source":"arxiv","date":"2026-10-27","topics":["Agent Safety","Reasoning","Planning","Evaluation","Reflection","Agent Framework"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.34649","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.34649.pdf","url":"https://arxiv.org/abs/2610.34649","abstract":"Recent advances in vision-language-action (VLA) and world-action models (WAMs) have significantly improved robotic manipulation, yet deploying robots in the open world demands a higher level of autonomy beyond executing predefined tasks. Robot agents offer a promising paradigm for this transition, integrating task discovery, contextual reasoning, physical execution, and adaptive recovery into a closed interaction loop. However, existing benchmarks largely evaluate isolated capabilities, failing to capture the complexity of open-world robot autonomy. We introduce RobotAgentBench (RAB), a comprehensive benchmark for evaluating robot agents in realistic, open-world household environments. Through an agent-assisted, human-in-the-loop real-to-sim pipeline, RAB constructs 50 diverse household layouts with interactive objects and physically grounded tasks, encompassing 90 atomic tasks, 18 short"},{"title":"Aerial-R1: Reinforcing Aerial Reasoning and Segmentation in MLLMs","authors":["Jisheng Dang","Huaiyuan Peng","Yixuan Wang","Kun Wang","Zhang Li","Tat-Seng Chua"],"submittedDate":"2026-10-19","tags":["Agent Safety","LLM Training","Reasoning","Hallucination","Evaluation"],"id":"arxiv:2610.33056","source":"arxiv","date":"2026-10-27","topics":["Agent Safety","LLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.33056","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.33056.pdf","url":"https://arxiv.org/abs/2610.33056","abstract":"While Multimodal Large Language Models (MLLMs) have revolutionized general visual perception, existing methods suffer from severe hallucination in the aerial domain, where extreme scale variations and visual ambiguity abound. Existing Supervised Fine-Tuning (SFT) paradigms force models to mimic ground truth without modeling uncertainty, often resulting in blind guessing on tiny or unrecognizable objects in aerial scenes. In this paper, we present Aerial-R1, the first aerial MLLM framework to reinforce visual reasoning capabilities for aerial reasoning and segmentation. Drawing inspiration from the reasoning-incentivizing mechanisms of DeepSeek-R1, we find that trustworthy perception stems from consistency across views, establishing a visual parallel to the Chain-of-Thought in logic. To effectively adapt policy optimization for non-autoregressive mask generation, we introduce Hybrid-View "},{"title":"Hallucination-Aware Multi-Agent RAG via Internal Attention Rewards","authors":["Runsong Jia","Qian Chang","Mengjia Wu","Ciprian Doru Giurcăneanu","Jie Lu","Yi Zhang"],"submittedDate":"2026-10-26","tags":["Agentic RAG","Agentic Search","Multi-Agent","Hallucination","Evaluation"],"id":"arxiv:2610.35056","source":"arxiv","date":"2026-10-27","topics":["Agentic RAG","Agentic Search","Multi-Agent","Hallucination","Evaluation","Fine-tuning"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35056","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.35056.pdf","url":"https://arxiv.org/abs/2610.35056","abstract":"Retrieval-augmented generation (RAG) grounds language models in retrieved evidence, but its outputs often contain claims unsupported by that evidence. Recent multi-agent RAG systems decompose the pipeline into cooperative decisions, yet they typically optimize all agents under a shared task reward such as EM or F1, which measures answer overlap rather than faithfulness to evidence. We propose a hallucination-aware multi-agent RAG framework that combines the task reward with an internal hallucination-risk signal computed from the generator's attention-head norms. Three role-specific LoRA adapters, a query planner, an evidence selector, and an answer generator, share a frozen backbone. A lightweight critic is trained once on TruthfulQA truthful/false pairs and then kept frozen, providing a complementary risk score that is added to the shared reward during cooperative PPO training. Across t"},{"title":"When Fine-Grained Credit Assignment Helps and Hurts: Multimodal Agentic Reinforcement Learning through Video Editing","authors":["Lei Zhao","Zongheng Cao","Xinyu Hu"],"submittedDate":"2026-10-26","tags":["Post-Training","Tool Use","Reasoning","Planning","Multimodal Agent"],"id":"arxiv:2610.35497","source":"arxiv","date":"2026-10-27","topics":["Post-Training","Tool Use","Reasoning","Planning","Multimodal Agent","RL for LLM"],"announceDate":"2026-10-27","arxiv":"https://arxiv.org/abs/2610.35497","upvotes":0,"pdf":"https://arxiv.org/pdf/2610.35497.pdf","url":"https://arxiv.org/abs/2610.35497","abstract":"Reinforcement learning (RL) has shown promise for training multimodal agents to reason and use tools. However, it remains unclear when fine-grained credit assignment improves learning and when it fails to improve task performance. Video editing provides a useful testbed for this question, combining multimodal perception, long-horizon planning, and tool use with delayed outcome feedback. We construct four movie-trailer editing task types---Content Selection, Narrative Sequencing, Rough Cut, and Fine Cut---that reflect real-world editing workflows and span different levels of task complexity and interaction horizon. Decaying process rewards provides the largest benefit on Fine Cut, with a 45.4% relative gain over outcome-only GRPO on tasks averaging more than 60 turns under outcome-only GRPO. On the three shorter-horizon task types averaging 30--40 turns under the same baseline, outcome-on"}],"archive":[],"latestPath":"data/latest.json"};
